package com.p2p.escrow.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*;
@Service public class JwtService { private final SecretKey key; private final long hours; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiry-hours}") long hours){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.hours=hours;} public String issue(UUID id){return Jwts.builder().subject(id.toString()).issuedAt(Date.from(Instant.now())).expiration(Date.from(Instant.now().plusSeconds(hours*3600))).signWith(key).compact();} public UUID parse(String token){return UUID.fromString(Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject());} }
